    setInitialPosition(points){
        this.chainCount = 0
        for(let  i = 0; i < points.length ; i++) {
            this.chain.push(new SnakeChain(this.ctx, points[i][0], points[i][1]));
            this.chainCount++
        }
        
    }
    setPosition(points){
        this.chain = []
        this.chainCount = 0
        for(let  i = 0; i < points.length ; i++) {
            this.chain.push(new SnakeChain(this.ctx, points[i][0], points[i][1]));
            this.chainCount++
        }
        
    }
    init(){
        this.chainCount = 0

        for(let  i = this.initCount -1; i >= 0 ; i--) {
            this.chain.push(new SnakeChain(this.ctx, i * this.size ,4));
            this.chainCount++
        }
        this.chain[0].color= 'blue'
        this.setLastTailPos()
        console.log(JSON.stringify(this.chain.map(i => i.position)));

    }

    setPath(path){
        this.path = path
    }

    reset(){
        this.chain = []
        this.direction = DIRECTIONS.RIGHT
        this.init()
    }

    setLastTailPos(){
        this.lastTailPos = [...this.chain[this.chain.length - 1].position]
    }
    move(){
        
        this.setLastTailPos()

        for(let i = this.chainCount-1; i > 0; i--){
            this.chain[i].position = [...this.chain[i-1].position]
        }

        this.moveHead()
    
    }

    changeDirection(direction){
        if (OPPOSITE_DIRECTIONS[this.direction] === direction) return;

        this.direction = direction
    }

    headCollidesWith(pos){
        return this.chain[0].collidesWith(pos)
    }

    headHitsBody(){
        let collided = false
        for(let  i = 1; i < this.chainCount; i++) {
            if(this.chain[0].collidesWith(this.chain[i].position)){
                collided = true
                console.log('head hits body:',this.chain[i].position,JSON.stringify(this.chain.map(i => i.position)))
                break
            }
        }
        return collided
    }

    headHitsWall(){
        
        if(
            this.chain[0].position[0] < 0 || this.chain[0].position[0] >= 400 
                || 
            this.chain[0].position[1] < 0 || this.chain[0].position[1] >= 400 
        ){
            console.log('head hits wall:')
            return true
        }
    }

    moveHead(){
        
        let next = this.path.shift();
        this.chain[0].position = [next[0], next[1]];
        
    }

    addChain(x,y){
        let newTail = new SnakeChain(this.ctx, this.lastTailPos[0] ,this.lastTailPos[1])
        this.chain.push(newTail);
        this.chainCount++
    }

    getHeadPosition(){
        return this.chain[0].position
    }
    
    update(){

        this.move()
        
    }

    draw(){

        for(let  i = 0; i < this.chainCount; i++) {
            this.chain[i].draw()
        }

    }


